namespace CardGame.Core;
internal static class MouSimaShiComposition
{
    [ProgramCatalogValidation(1860)] internal static void Validate(string path, SkillProgram p)
    {
        var ops = new[] { SkillProgramEffectOp.InitializeMouSimaShiSanshi, SkillProgramEffectOp.RecoverMouSimaShiSanshi, SkillProgramEffectOp.ResolveMouSimaShiZhenrao, SkillProgramEffectOp.ResolveMouSimaShiChenlve, SkillProgramEffectOp.RemoveMouSimaShiChenlve, SkillProgramEffectOp.ReturnMouSimaShiChenlve };
        if (p.Id is not (MouSimaShiRuntime.Sanshi or MouSimaShiRuntime.Zhenrao or MouSimaShiRuntime.Chenlve) && !p.Activations.SelectMany(a => a.Effects).Concat(p.Triggers.SelectMany(t => t.Effects)).Any(e => ops.Contains(e.Op))) return;
        bool T(SkillProgramTrigger t, string id, SkillProgramTriggerWindow w, SkillProgramEffectOp op, bool optional) => t.Id == id && t.Window == w && t.Optional == optional && t.Effects is [{ Op: var effect, Target: SkillProgramEffectTarget.Owner, Condition.Kind: SkillProgramConditionKind.Always }] && effect == op;
        var sanshi = p.Id == MouSimaShiRuntime.Sanshi && p.Activations.Count == 0 && p.Triggers.Count == 3 && T(p.Triggers[0], "mark-ranks", SkillProgramTriggerWindow.GameStarting, ops[0], false) && T(p.Triggers[1], "turn-discard-return", SkillProgramTriggerWindow.TurnEnding, ops[1], false) && p.Triggers[1].TurnOwnerScope == SkillProgramTurnOwnerScope.Own && T(p.Triggers[2], "other-turn-discard-return", SkillProgramTriggerWindow.TurnEnding, ops[1], false) && p.Triggers[2].TurnOwnerScope == SkillProgramTurnOwnerScope.OtherLiving;
        var zhenrao = p.Id == MouSimaShiRuntime.Zhenrao && p.Activations.Count == 0 && p.Triggers.Count == 2 && T(p.Triggers[0], "use-other-targets", SkillProgramTriggerWindow.CardUseTargetsFinalized, ops[2], true) && p.Triggers[0].OwnerRelation == SkillProgramCardActionOwnerRelation.Actor && T(p.Triggers[1], "targeted-by-other", SkillProgramTriggerWindow.CardUseTargetsFinalized, ops[2], true) && p.Triggers[1].OwnerRelation == SkillProgramCardActionOwnerRelation.Target;
        var chenlve = p.Id == MouSimaShiRuntime.Chenlve && p.Activations is [{ Id: "claim-dead-soldiers", MinCards: 0, MaxCards: 0, MinTargets: 0, MaxTargets: 0, UsesPerGame: 1, Effects: [{ Op: SkillProgramEffectOp.ResolveMouSimaShiChenlve, Target: SkillProgramEffectTarget.Owner, Condition.Kind: SkillProgramConditionKind.Always }] }] && p.Triggers.Count == 2 && T(p.Triggers[0], "remove-issued-entities", SkillProgramTriggerWindow.ActualPhaseEnded, ops[4], false) && T(p.Triggers[1], "death-return-shuffle", SkillProgramTriggerWindow.OwnerDied, ops[5], false);
        if ((!sanshi && !zhenrao && !chenlve) || p.Modifiers.Count != 0 || p.ViewAs.Count != 0 || p.CardPolicies.Count != 0 || p.BooleanStates.Count != 0 || p.DamageModifiers.Count != 0) throw new InvalidOperationException(path + ": Mou Sima Shi requires the immutable native rank marks, exact per-peer actual-use damage and actual-Play entity quarantine/death shuffle.");
    }
}
